#!/usr/bin/env perl
use strict;
use warnings;
use Getopt::Long;
use File::Basename qw(dirname);
use File::Path qw(make_path);
use Cwd qw(abs_path);

# ============================================================
# Script: extract_valid_tlen.pl
#
# Purpose:
#   Extract sampled positive TLEN values from valid paired-end reads.
#
# Pipeline logic:
#   This script is intended to run on SAMPLE.target.bam generated by
#   extract_target_bam.pl, not on the original whole-genome BAM.
#
# Design principle:
#   Command-line arguments only define runtime I/O:
#     --config
#     --bam
#     --out
#
#   All analysis parameters are read from config:
#     SAMTOOLS
#     MIN_MAPQ
#     EXCLUDE_DUPLICATES
#     TLEN_MAX_PAIRS
#     TLEN_THREADS
#     TLEN_RANDOM_SEED
#
# Output:
#   ReadName    TLEN
#
# Notes:
#   1. Only TLEN > 0 is retained to avoid counting the same paired-end
#      fragment twice.
#   2. Properly paired reads are required.
#   3. Unmapped, mate-unmapped, secondary and supplementary alignments
#      are always excluded.
#   4. Duplicate reads are excluded only when EXCLUDE_DUPLICATES=1.
#   5. Reservoir sampling is used when the number of valid TLEN values
#      exceeds TLEN_MAX_PAIRS. This avoids positional bias caused by
#      simply taking the first N records from a coordinate-sorted BAM.
# ============================================================

my $config;
my $bam;
my $out;
my $help = 0;

GetOptions(
    "config=s" => \$config,
    "bam=s"    => \$bam,
    "out=s"    => \$out,
    "help"     => \$help,
) or die usage();

if ($help) {
    print usage();
    exit 0;
}

die usage()
    unless defined $config
        && defined $bam
        && defined $out;

# -----------------------------
# Validate runtime I/O
# -----------------------------
$config = abs_path($config) if -e $config;
die "[ERROR] Config file not found: $config\n"
    unless defined $config && -s $config;
die "[ERROR] Config path must be absolute after resolution: $config\n"
    unless $config =~ m{^/};

$bam = abs_path($bam) if -e $bam;
die "[ERROR] BAM file not found: $bam\n"
    unless defined $bam && -s $bam;
die "[ERROR] BAM path must be absolute after resolution: $bam\n"
    unless $bam =~ m{^/};
die "[ERROR] BAM file must end with .bam: $bam\n"
    unless $bam =~ /\.bam$/i;

die "[ERROR] Output path must be absolute: $out\n"
    unless defined $out && $out =~ m{^/};

my $out_parent = dirname($out);
make_path($out_parent) unless -d $out_parent;
die "[ERROR] Cannot create output directory: $out_parent\n"
    unless -d $out_parent;

# -----------------------------
# Read config
# -----------------------------
my %CONF = read_config($config);

my $samtools = get_conf_required(\%CONF, "SAMTOOLS");
my $min_mapq = get_conf_required(\%CONF, "MIN_MAPQ");
my $exclude_duplicates = get_conf_required(\%CONF, "EXCLUDE_DUPLICATES");
my $max_pairs = get_conf_required(\%CONF, "TLEN_MAX_PAIRS");
my $threads = get_conf_required(\%CONF, "TLEN_THREADS");
my $random_seed = get_conf_required(\%CONF, "TLEN_RANDOM_SEED");

validate_nonnegative_integer("MIN_MAPQ", $min_mapq);
validate_bool_01("EXCLUDE_DUPLICATES", $exclude_duplicates);
validate_positive_integer("TLEN_MAX_PAIRS", $max_pairs);
validate_positive_integer("TLEN_THREADS", $threads);
validate_integer("TLEN_RANDOM_SEED", $random_seed);

check_executable($samtools, "SAMTOOLS");

# -----------------------------
# SAM flags
# -----------------------------

# Require:
#   0x2 = properly paired
my $REQUIRE_FLAG = 2;

# Exclude by default:
#   0x4   read unmapped
#   0x8   mate unmapped
#   0x100 secondary alignment
#   0x800 supplementary alignment
my $EXCLUDE_FLAG = 4 + 8 + 256 + 2048;

# Optionally exclude:
#   0x400 duplicate
if ($exclude_duplicates == 1) {
    $EXCLUDE_FLAG += 1024;
}

# -----------------------------
# Reservoir sampling setup
# -----------------------------
srand($random_seed);

my @reservoir;
my $total_records_after_samtools_filter = 0;
my $valid_positive_tlen_count = 0;

# -----------------------------
# Run samtools
# -----------------------------
open my $SAM, "-|",
    $samtools, "view",
    "-@", $threads,
    "-f", $REQUIRE_FLAG,
    "-F", $EXCLUDE_FLAG,
    "-q", $min_mapq,
    $bam
    or die "[ERROR] Failed to run samtools view on BAM: $bam\n";

while (my $line = <$SAM>) {
    chomp $line;
    next if $line =~ /^\s*$/;

    my @f = split /\t/, $line, 12;
    next unless @f >= 9;

    $total_records_after_samtools_filter++;

    my $read_name = $f[0];
    my $tlen      = $f[8];

    next unless defined $read_name && $read_name ne "";
    next unless defined $tlen && $tlen =~ /^-?\d+$/;

    # Keep only positive TLEN to count each paired-end fragment once.
    next unless $tlen > 0;

    $valid_positive_tlen_count++;

    if (@reservoir < $max_pairs) {
        push @reservoir, [ $read_name, $tlen ];
    } else {
        # Reservoir sampling:
        # For the nth valid item, randomly replace one existing item
        # with probability max_pairs / n.
        my $j = int(rand($valid_positive_tlen_count));
        if ($j < $max_pairs) {
            $reservoir[$j] = [ $read_name, $tlen ];
        }
    }
}

close $SAM
    or die "[ERROR] samtools view command failed for BAM: $bam\n";

# -----------------------------
# Write output
# -----------------------------
open my $OUT, ">", $out
    or die "[ERROR] Cannot write output file: $out\n";

print $OUT join("\t", "ReadName", "TLEN"), "\n";

for my $item (@reservoir) {
    print $OUT join("\t", @$item), "\n";
}

close $OUT;

die "[ERROR] TLEN output was not generated: $out\n"
    unless -s $out;

# -----------------------------
# Summary
# -----------------------------
print "[INFO] Done.\n";
print "[INFO] Config: $config\n";
print "[INFO] BAM: $bam\n";
print "[INFO] Output: $out\n";
print "[INFO] SAMTOOLS: $samtools\n";
print "[INFO] MIN_MAPQ: $min_mapq\n";
print "[INFO] EXCLUDE_DUPLICATES: $exclude_duplicates\n";
print "[INFO] TLEN_THREADS: $threads\n";
print "[INFO] TLEN_MAX_PAIRS: $max_pairs\n";
print "[INFO] TLEN_RANDOM_SEED: $random_seed\n";
print "[INFO] Require FLAG: $REQUIRE_FLAG\n";
print "[INFO] Exclude FLAG: $EXCLUDE_FLAG\n";
print "[INFO] Total records after samtools filtering: $total_records_after_samtools_filter\n";
print "[INFO] Valid positive TLEN count: $valid_positive_tlen_count\n";
print "[INFO] Output TLEN count: " . scalar(@reservoir) . "\n";

if ($valid_positive_tlen_count == 0) {
    warn "[WARNING] No valid positive TLEN values were extracted. Please check BAM file and filtering criteria.\n";
}

if ($valid_positive_tlen_count > $max_pairs) {
    print "[INFO] Reservoir sampling was applied because valid TLEN count exceeded TLEN_MAX_PAIRS.\n";
}

exit 0;

# ============================================================
# Config helpers
# ============================================================

sub read_config {
    my ($file) = @_;

    my %conf;

    open my $FH, "<", $file
        or die "[ERROR] Cannot open config file: $file\n";

    while (my $line = <$FH>) {
        chomp $line;
        $line =~ s/\r$//;

        next if $line =~ /^\s*$/;
        next if $line =~ /^\s*#/;

        # Remove inline comments:
        # KEY=value   # comment
        $line =~ s/\s+#.*$//;

        next unless $line =~ /^\s*([^=\s]+)\s*=\s*(.*?)\s*$/;

        my ($key, $val) = ($1, $2);

        $key =~ s/^\s+|\s+$//g;
        $val =~ s/^\s+|\s+$//g;

        # Remove one pair of simple quotes if present.
        $val =~ s/^['"]//;
        $val =~ s/['"]$//;

        die "[ERROR] Empty config key found in $file\n"
            if $key eq "";

        $conf{$key} = $val;
    }

    close $FH;

    return %conf;
}

sub get_conf_required {
    my ($conf_ref, $key) = @_;

    die "[ERROR] Required config parameter missing: $key\n"
        unless exists $conf_ref->{$key}
            && defined $conf_ref->{$key}
            && $conf_ref->{$key} ne "";

    return $conf_ref->{$key};
}

# ============================================================
# Validation helpers
# ============================================================

sub validate_bool_01 {
    my ($name, $v) = @_;

    die "[ERROR] $name must be 0 or 1. Observed: $v\n"
        unless defined $v && $v =~ /^[01]$/;

    return 1;
}

sub validate_integer {
    my ($name, $v) = @_;

    die "[ERROR] $name must be an integer. Observed: $v\n"
        unless defined $v && $v =~ /^-?\d+$/;

    return 1;
}

sub validate_positive_integer {
    my ($name, $v) = @_;

    die "[ERROR] $name must be a positive integer. Observed: $v\n"
        unless defined $v && $v =~ /^\d+$/ && $v >= 1;

    return 1;
}

sub validate_nonnegative_integer {
    my ($name, $v) = @_;

    die "[ERROR] $name must be a non-negative integer. Observed: $v\n"
        unless defined $v && $v =~ /^\d+$/ && $v >= 0;

    return 1;
}

sub check_executable {
    my ($cmd, $name) = @_;

    die "[ERROR] Empty executable path for $name\n"
        unless defined $cmd && $cmd ne "";

    if ($cmd =~ m{/}) {
        die "[ERROR] $name executable not found or not executable: $cmd\n"
            unless -x $cmd;
    } else {
        my $ret = system("command -v $cmd >/dev/null 2>&1");

        die "[ERROR] $name executable not found in PATH: $cmd\n"
            if $ret != 0;
    }

    return 1;
}

sub usage {
    return <<'USAGE';
Usage:
  perl bin/extract_valid_tlen.pl \
    --config /abs/path/conf/hcm_exondel.conf \
    --bam /abs/path/SAMPLE.target.bam \
    --out /abs/path/SAMPLE.valid_tlen.tsv

Required config parameters:
  SAMTOOLS
  MIN_MAPQ
  EXCLUDE_DUPLICATES
  TLEN_MAX_PAIRS
  TLEN_THREADS
  TLEN_RANDOM_SEED

Notes:
  1. This script is intended to run on SAMPLE.target.bam, not the original WGS BAM.
  2. Only TLEN > 0 is retained.
  3. Reservoir sampling is used when valid TLEN count exceeds TLEN_MAX_PAIRS.
  4. Command-line arguments only define runtime input/output identity.
  5. All analysis parameters are read from the config file.
USAGE
}


